function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'CustomStack' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with CustomStack(maxSize).';
  const inRange = (v, low, high) => Number.isInteger(v) && v >= low && v <= high;
  if (!inRange(args[0][0], 1, 1000)) return 'maxSize is a whole number from 1 to 1000.';
  const counts = { push: 0, pop: 0, increment: 0 };
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'push') {
      if (a.length !== 1 || !inRange(a[0], 1, 1000)) return 'push takes one value x from 1 to 1000.';
    } else if (operations[i] === 'pop') {
      if (a.length !== 0) return 'pop takes no arguments.';
    } else if (operations[i] === 'increment') {
      if (a.length !== 2 || !inRange(a[0], 1, 1000)) return 'increment needs k from 1 to 1000 and a val.';
      if (!inRange(a[1], 0, 100)) return 'increment val is from 0 to 100.';
    } else {
      return 'Only push, pop and increment can follow the constructor.';
    }
    if (++counts[operations[i]] > 1000) return 'Each method is called at most 1000 times.';
  }
  return null;
}

