class CustomStack {
  constructor(maxSize) {
    this.maxSize = maxSize;
    this.stack = [];
    this.pending = [];
  }

  push(x) {
    if (this.stack.length < this.maxSize) {
      this.stack.push(x);
      this.pending.push(0);
    }
  }

  pop() {
    if (this.stack.length === 0) {
      return -1;
    }
    const top = this.stack.length - 1;
    const extra = this.pending.pop();
    if (top > 0) {
      this.pending[top - 1] += extra;
    }
    return this.stack.pop() + extra;
  }

  increment(k, val) {
    const index = Math.min(k, this.stack.length) - 1;
    if (index >= 0) {
      this.pending[index] += val;
    }
  }
}

