class CustomStack {
  constructor(maxSize) {
    this.limit = maxSize;
    this.items = [];
  }
  push(x) {
    if (this.items.length === this.limit) return;
    this.items.push(x);
  }
  pop() {
    return this.items.length ? this.items.pop() : -1;
  }
  increment(k, val) {
    for (let i = 0; i < this.items.length && i < k; i++) this.items[i] += val;
  }
}

