function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const maxSize = large ? (rand() < 0.5 ? int(1, 1000) : int(1, 30)) : int(1, 5);
  const calls = large ? 499 : int(1, 15);
  const pushRate = 0.25 + rand() * 0.35;
  const popRate = 0.15 + rand() * 0.25;
  const kLimit = rand() < 0.5 ? Math.min(1000, maxSize + 3) : 1000;
  const operations = ['CustomStack'];
  const args = [[maxSize]];
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (roll < pushRate) {
      operations.push('push');
      args.push([int(1, large ? 1000 : 9)]);
    } else if (roll < pushRate + popRate) {
      operations.push('pop');
      args.push([]);
    } else {
      operations.push('increment');
      args.push([int(1, kLimit), rand() < 0.15 ? 0 : int(1, large ? 100 : 9)]);
    }
  }
  return [operations, args];
}
